from datetime import date, timedelta

class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays else set()
        self._used: dict[tuple[str, int], int] = {}

    def _leave_days(self, start: date, end: date) -> int:
        """Count working days (weekdays excluding holidays) between start and end inclusive."""
        count = 0
        current = start
        one_day = timedelta(days=1)
        while current <= end:
            if current.weekday() < 5 and current not in self.holidays:
                count += 1
            current += one_day
        return count

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        if end < start:
            raise ValueError("End date cannot be before start date")
        # Less than 3 days notice: (start - today) must be >= 3 days
        if (start - today) < timedelta(days=3):
            raise ValueError("Requests must be made at least 3 days in advance")

        days = self._leave_days(start, end)

        # A leave request spanning multiple years is rejected implicitly by
        # attributing all days to the start year; simpler to raise if it spans years.
        if start.year != end.year:
            raise ValueError("Leave request cannot span multiple years")

        year = start.year
        used = self._used.get((employee, year), 0)
        remaining = self.days_per_year - used
        if days > remaining:
            raise ValueError("Insufficient leave balance")

        self._used[(employee, year)] = used + days
        return days

    def remaining(self, employee: str, year: int) -> int:
        used = self._used.get((employee, year), 0)
        return self.days_per_year - used
